id_fkey": "FOREIGN KEY (quote_id) REFERENCES public.commercial_artwork_change_quotes(id)"}, "columns_sha256": "bd12649ef1fd07fc3981d36f26749d7923235530a65643eabbedea10b4c6718c"}, {"acl": ["service_role:SELECT"], "rls": true, "table": "public.commercial_artwork_change_quotes", "indexes": {"cacq_numero": "CREATE UNIQUE INDEX cacq_numero ON public.commercial_artwork_change_quotes USING btree (request_id, quote_no)", "cacq_um_aberto_idx": "CREATE UNIQUE INDEX cacq_um_aberto_idx ON public.commercial_artwork_change_quotes USING btree (request_id) WHERE (status = 'open'::text)", "commercial_artwork_change_quotes_pkey": "CREATE UNIQUE INDEX commercial_artwork_change_quotes_pkey ON public.commercial_artwork_change_quotes USING btree (id)"}, "present": true, "policies": {}, "rls_forced": false, "constraints": {"cacq_escopo": "CHECK ((length(btrim(scope)) >= 5))", "cacq_numero": "UNIQUE (request_id, quote_no)", "cacq_status": "CHECK ((status = ANY (ARRAY['open'::text, 'superseded'::text, 'accepted'::text])))", "cacq_valores": "CHECK (((pieces_count > 0) AND (supplier_total_cents > 0) AND (cap_cents >= supplier_total_cents) AND ((supplier_unit_cost_cents IS NULL) OR ((supplier_unit_cost_cents > 0) AND ((pieces_count * supplier_unit_cost_cents) = supplier_total_cents)))))", "cacq_concilia": "TRIGGER DEFERRABLE INITIALLY DEFERRED", "cacq_documento": "CHECK (((length(btrim(supplier_document_reference)) >= 5) AND (supplier_document_sha256 ~ '^[0-9a-f]{64}$'::text)))", "cacq_fornecedor": "CHECK ((length(btrim(supplier_name)) >= 2))", "cacq_nao_incluidos": "CHECK ((excluded_items @> ARRAY['frete'::text, 'criacao_de_arte'::text, 'instalacao'::text, 'tributos'::text, 'servicos'::text]))", "commercial_artwork_change_quotes_pkey": "PRIMARY KEY (id)", "commercial_artwork_change_quotes_request_id_fkey": "FOREIGN KEY (request_id) REFERENCES public.commercial_artwork_change_requests(id)", "commercial_artwork_change_quotes_artwork_version_id_fkey": "FOREIGN KEY (artwork_version_id) REFERENCES