DO $verifica_r43$
DECLARE
  v_pre jsonb;
BEGIN
  IF (SELECT status FROM public.commercial_pricing_rules WHERE version = 3) <> 'active'
     OR (SELECT status FROM public.commercial_pricing_rules WHERE version = 4) <> 'prepared'
     OR EXISTS (SELECT 1 FROM public.commercial_pricing_rules WHERE enabled_settlement_modes IS NOT NULL) THEN
    RAISE EXCEPTION 'r43_verificacao: a migration nao ativa versao nem habilita modalidade';
  END IF;
  IF EXISTS (SELECT 1 FROM public.commercial_pricing_activation_log)
     OR EXISTS (SELECT 1 FROM public.commercial_pricing_activation_approvals)
     OR EXISTS (SELECT 1 FROM public.commercial_qa_operational_procedures) THEN
    RAISE EXCEPTION 'r43_verificacao: ativacao, aprovacao ou procedimento de QA nao nascem aqui';
  END IF;
  IF (SELECT string_agg(manifest_label, ',' ORDER BY id) FROM public.commercial_guard_manifests) <> 'R4.1,R4.2,R4.2.1,R4.3'
     OR (SELECT catalog_sha256 FROM public.commercial_guard_manifests ORDER BY id DESC LIMIT 1) <> '0cab0fb36136652841593665b3cc481ab57454cfd939d389204df8f789198a79' THEN
    RAISE EXCEPTION 'r43_verificacao: historico de manifestos ou manifesto vigente diferente do publicado';
  END IF;
  IF coalesce(array_length(public.commercial_guard_integrity_failures(), 1), 0) > 0 THEN
    RAISE EXCEPTION 'r43_verificacao: guardas divergentes: %', public.commercial_guard_integrity_failures();
  END IF;
  v_pre := public.commercial_pricing_activation_preflight(4);
  IF (v_pre->>'ok')::boolean OR NOT (v_pre->'failures' ? 'qa_operational_procedure_missing:SF-v1.5') THEN
    RAISE EXCEPTION 'r43_verificacao: sem habilitacao, a versao 4 continua exigindo a QA: %', v_pre;
  END IF;
END $verifica_r43$;
